package com.bank.indexer.service;

import com.bank.indexer.dto.IndexResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class NarrationIndexerService {

    public IndexResult extractUniqueWords(String narration) {
        String[] words = narration.split("\\s+");

        // Unique words — sorted alphabetically
        List<String> uniqueSorted = Arrays.stream(words)
            .map(String::toLowerCase)
            .map(w -> w.replaceAll("[^a-z0-9]", ""))  // remove punctuation
            .filter(w -> !w.isBlank())
            .distinct()
            .sorted()
            .toList();

        // Unique words — first-occurrence order (LinkedHashSet)
        List<String> uniqueOrdered = Arrays.stream(words)
            .map(String::toLowerCase)
            .map(w -> w.replaceAll("[^a-z0-9]", ""))
            .filter(w -> !w.isBlank())
            .collect(Collectors.toCollection(LinkedHashSet::new))
            .stream().toList();

        return new IndexResult(narration, words.length, uniqueSorted.size(),
            uniqueSorted, uniqueOrdered);
    }
}
