package com.bank.indexer.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class UniqueWordsTest {

    @Test
    void uniqueWordsSorted() {
        List<String> unique = Arrays.stream("NEFT transfer to savings NEFT credit from savings".split("\\s+"))
            .map(String::toLowerCase).distinct().sorted().toList();
        assertThat(unique).containsExactly("credit", "from", "neft", "savings", "to", "transfer");
    }

    @Test
    void preserveFirstOccurrenceOrder() {
        List<String> ordered = Arrays.stream("NEFT transfer to savings NEFT".split("\\s+"))
            .map(String::toLowerCase)
            .collect(Collectors.toCollection(LinkedHashSet::new))
            .stream().toList();
        assertThat(ordered).containsExactly("neft", "transfer", "to", "savings");
    }

    @Test
    void handlesPunctuation() {
        List<String> unique = Arrays.stream("Hello, world! Hello.".split("\\s+"))
            .map(String::toLowerCase)
            .map(w -> w.replaceAll("[^a-z0-9]", ""))
            .distinct().sorted().toList();
        assertThat(unique).containsExactly("hello", "world");
    }

    @Test
    void singleWord() {
        List<String> unique = Arrays.stream("RELIANCE".split("\\s+"))
            .map(String::toLowerCase).distinct().toList();
        assertThat(unique).containsExactly("reliance");
    }
}
